"""Curriculum order: introduce each operation before requiring it in a task."""
CHANGED=list(range(1,19))+[20,21,22,23,24,26,32,33,42,48,49,52,55,61,62,68,69,70,72,79,85]
def apply(L):
 def change(n,**values):L[n].update(values)
 change(1,mode='study',code='O‘quvchi kutubxona saytida kitob nomini ko‘radi, kerakli bo‘limni tanlaydi va ma’lumotni o‘qiydi. U ko‘rib, ishlatayotgan sahifa — frontend interfeysiga misol.',task='Kundalik foydalanadigan bitta saytni eslang. Uning foydalanuvchisi kim, u yerda qanday ma’lumot ko‘rinadi va foydalanuvchi qanday ish bajaradi? Og‘zaki izohlang.',expected='O‘quvchi frontendning vazifasini o‘z so‘zlari bilan tushuntiradi va hayotiy misol keltiradi.',teaching='Frontendni foydalanuvchi bilan aloqa qismi sifatida ko‘ring: saytning maqsadi, undagi axborot va odam bajara oladigan amallarni ajrating. HTML, CSS va JavaScript nomlarini bu darsda faqat umumiy texnologiyalar sifatida eshitasiz; ularning kodini yozish talab qilinmaydi.',prerequisite='Boshlang‘ich mavzu. Dasturlash tajribasi talab qilinmaydi.')
 change(2,mode='study',code='Brauzerda sayt manzili kiritiladi. Brauzer serverga so‘rov yuboradi; server javob qaytaradi; brauzer sahifani ko‘rsatadi. Bitta sayt bir nechta sahifadan iborat bo‘lishi mumkin.',task='Internet va WWWni, sayt va sahifani, brauzer va serverni juftlab farqlang. Saytni ochish jarayonini oddiy gaplar bilan ketma-ket ayting.',expected='O‘quvchi uch juft tushunchaning farqini va brauzer–server aloqasining asosiy ketma-ketligini aytadi.',teaching='Internet — aloqa infratuzilmasi, WWW — uning ustidagi veb-xizmat. Brauzer so‘rovchi dastur, server javob beruvchi tizim. URL — manzil; ushbu bosqichda murakkab query yoki fragmentni yozish va HTML havola yaratish so‘ralmaydi.',prerequisite='1-mavzu: frontend va foydalanuvchi interfeysi.')
 change(3,mode='study',code='Kutubxona sahifasidagi kitob nomi va tugma foydalanuvchiga ko‘rinadi — frontend. Serverda kitobning mavjudligini tekshirish — backend. Tuzilma, ko‘rinish va xatti-harakatning vazifalari bir-biridan farq qiladi.',task='Kitobni qidirish misolida foydalanuvchiga ko‘rinadigan va serverda bajariladigan ishlarni ajrating. HTML, CSS va JavaScriptning vazifasini bir jumladan ayting. Kod yozmang.',expected='O‘quvchi frontend va backend ishlarini ajratadi; HTMLni tuzilma, CSSni ko‘rinish, JavaScriptni xatti-harakat bilan bog‘laydi.',teaching='Avval interfeysdagi ko‘rinadigan ma’lumot va amallarni toping. Keyin serverda bajarilishi mumkin bo‘lgan tekshirishni ajrating. Uch texnologiya nomi ularning vazifasini taqqoslash uchun beriladi: email formasi, CSS qoidasi yoki JavaScript dasturi hali yaratilmaydi.',prerequisite='1–2-mavzular: interfeys, brauzer va server.')
 change(4,mode='files',code='frontend-loyiha/\n  index.html\n  assets/',task='Kompyuterda frontend-loyiha papkasini oching. VS Code orqali shu papkada bo‘sh index.html fayli va assets papkasini yarating. Fayl nomi va kengaytmasini tekshiring, saqlang va brauzerda oching.',expected='VS Codedagi papka daraxtida index.html va assets ko‘rinadi. Bo‘sh index.html brauzerda bo‘sh sahifa ochishi tabiiy; HTML kodi keyingi mavzuda o‘rganiladi.',teaching='VS Code menyusidan File → Open Folder orqali papkani oching. New File bilan index.html, New Folder bilan assets yarating. Faylni saqlang va fayl menejeridan brauzerda oching. Muharrir faylni tahrirlaydi, brauzer uni ko‘rsatadi. Hozircha hech qanday HTML tegi yozilmaydi.',prerequisite='1–3-mavzular: frontend va brauzer vazifalari.')
 change(5,code='<!doctype html>\n<html lang="uz">\n<head>\n  <meta charset="UTF-8">\n  <title>Mening sahifam</title>\n</head>\n<body>Salom, bu mening birinchi sahifam.</body>\n</html>',task='Berilgan HTML skeletida faqat title matni va body ichidagi oddiy matnni o‘zgartiring. Hujjatni ko‘ring; brauzer yorlig‘i bilan sahifadagi matnni farqlang.',expected='Brauzer yorlig‘ida title matni, sahifada esa body ichidagi matn ko‘rinadi. Sarlavha yoki paragraf teglari bu topshiriqda kerak emas.',teaching='DOCTYPE standart hujjat rejimini bildiradi. html ildiz element, lang asosiy til, head xizmat ma’lumotlari, meta charset matn kodlanishi, title brauzer yorlig‘i nomi, body ko‘rinadigan mazmundir. Hozir faqat shu skelet va oddiy matn bilan ishlang; h1 va p 7-mavzuda o‘rganiladi.')
 change(6,code='<div title="Tashqi element">\n  <span title="Ichki element">HTML elementlari</span>\n</div>',task='Namunadagi tashqi va ichki elementni, ochuvchi va yopuvchi teglarni toping. title atributining qiymatini o‘zgartiring. span tegini divdan oldin yopib, ichma-ichlikni saqlang.',expected='Ichki matn ko‘rinadi; sichqoncha matn ustida ushlansa title izohi chiqishi mumkin. Ichki element tashqi elementdan oldin yopilgan.',teaching='Teg — <div> kabi yozuv; element uning mazmuni bilan birga qaraladi. Bu misolda div tashqi guruh, span ichki matn guruhidir; bezak berilmagan. title atributi izoh matnini beradi. Yopuvchi tegda / yoziladi. Ichma-ich teglar teskari tartibda yopiladi. class orqali CSS yoki strong orqali formatlash hali vazifa emas.')
 change(7,teaching='h1 asosiy sarlavha, h2 uning ostidagi bo‘lim sarlavhasidir; h1–h6 darajalari mazmun iyerarxiyasini bildiradi. p paragrafni, br ma’noli satr uzilishini, hr mavzuviy ajralishni bildiradi. Endi shu teglar bilan mashq qiling; rang va shriftni o‘zgartirish talab qilinmaydi.',pitfall='Sarlavha darajasini faqat kattaroq yozuv olish uchun tanlamang. br bilan katta bo‘shliqlar yasamang; bu darsda sahifa dizayni talab qilinmaydi.')
 change(8,teaching='strong muhim mazmun, em urg‘u, b e’tibor jalb qiluvchi matn uchun ishlatiladi. &lt; va &gt; belgisi tegni matn sifatida ko‘rsatadi; &amp; — ampersand, &copy; — mualliflik belgisi. Avval belgilarni qanday yozishni o‘qing, keyin namuna ichidagi matnni tahrirlang.')
 change(9,code='<a href="#aloqa">Aloqa bo‘limi</a>\n<a href="https://developer.mozilla.org/" target="_blank" rel="noopener">MDN qo‘llanmasi</a>\n<p id="aloqa">Aloqa: Namangan shahar 3-sonli texnikum</p>',teaching='a havola yaratadi, href manzilni belgilaydi. href="#aloqa" shu hujjatdagi id="aloqa" nishoniga boradi. target="_blank" alohida oynani tanlaydi; rel="noopener" ochilgan oynaga tegishli bog‘lanishni cheklaydi. Bu darsda section yoki nav kerak emas; ular 13-mavzuda tushuntiriladi.')
 change(10,code='<img src="https://web-talim-abdukarim-2026.satinyacorn67.chatgpt.site/assets/texnikum-building-2026.jpg"\n     alt="Namangan shahar 3-sonli texnikum binosi" width="300">',task='Namunadagi rasmni ko‘ring. alt matnini rasm mazmuniga mos qayta yozing. width qiymatini 200 va 300 qilib solishtiring. src manzilini ataylab xato qilib, matnli muqobilning vazifasini kuzating.',expected='To‘g‘ri src bilan texnikum rasmi ko‘rinadi. Rasm yuklanmasa, alt uning mazmunini tushuntiradi. CSS yordamida karta yoki responsive maket qurish so‘ralmaydi.',teaching='img rasmni joylaydi va yopuvchi teg olmaydi. src rasm manzili, alt rasm mazmunining matnli muqobili, width esa namuna uchun piksel kengligidir. Internetga ulanish rasmni yuklash uchun kerak. O‘z loyihangizda assets ichidagi rasmga nisbiy yo‘l ham ishlatiladi; SVG yozish va CSS bezash bu darsning vazifasi emas.')
 change(11,teaching='ul tartibsiz, ol tartibli ro‘yxatni boshlaydi. Har bir band li ichida yoziladi. Ichma-ich ro‘yxat tashqi li ichiga qo‘yiladi va yopiladi. Ro‘yxatdagi CSS yoki JavaScript so‘zlari oddiy kontentdir; ularning kodini yozish shart emas.')
 change(12,teaching='table jadval, caption uning nomi, tr satr, th sarlavha katagi, td ma’lumot katagidir. thead sarlavha satrlarini, tbody ma’lumot satrlarini guruhlaydi. scope="col" sarlavha qaysi ustunga tegishli ekanini bildiradi. Katak chegarasi, rang va padding CSS bo‘limida o‘rganiladi; hozir HTML tuzilishi tekshiriladi.')
 change(13,teaching='header kirish qismi, nav navigatsiya, main asosiy mazmun, section mavzuviy bo‘lim, article mustaqil mazmun, footer yakun qismidir. Tegni ma’nosiga qarab tanlang. Ushbu teglar avtomatik ustun, rang yoki interaktiv menyu yaratmaydi; vazifa faqat ma’noli HTML tuzilmasini qurishdir.')
 change(14,task='Faqat HTML bilan uch bo‘limli sahifa tuzing. nav ichidagi uchta a havolasini bo‘limlarning id qiymatlariga ulang va har bir o‘tishni sinang. Yashiriladigan menyu yoki JavaScript hodisasi kerak emas.',teaching='13-mavzudagi nav, main va sectionni 9-mavzudagi a, href va id bilan birlashtiring. Har nishonning idsi yagona bo‘lsin. Havola bosilishi brauzerning HTML funksiyasi bilan bo‘limga o‘tadi; buning uchun JavaScript yozilmaydi.')
 change(15,teaching='form maydonlarni guruhlaydi. input matn oladi; type="email" email shaklini brauzerga bildiradi, name maydon nomi, id esa label bilan bog‘lanish nuqtasi. label for qiymati input id qiymatiga teng bo‘ladi. required bo‘sh qiymatni HTML orqali cheklaydi. button type="submit" brauzer tekshiruvini chaqiradi. Bu misolda ma’lumot serverga yuborilmaydi; JavaScript validatsiyasi hali talab qilinmaydi.',task='Ism va email maydonli HTML forma tuzing; har maydonga label, name va required qo‘shing. Yuborish tugmasini bosing va brauzerning bo‘sh yoki noto‘g‘ri email uchun chiqargan xabarini kuzating. JavaScript yozmang.')
 change(16,code='<form>\n<label for="kurs">Kurs</label><select id="kurs" name="kurs"><option>HTML</option><option>Keyingi kurs</option></select>\n<label><input type="radio" name="vaqt" value="ertalab"> Ertalab</label>\n<label><input type="radio" name="vaqt" value="kechqurun"> Kechqurun</label>\n<label><input type="checkbox" name="rozilik"> Shartlarni o‘qidim</label>\n<label for="izoh">Izoh</label><textarea id="izoh" name="izoh"></textarea>\n<button type="submit">Yuborish</button>\n</form>',teaching='select ro‘yxatdan tanlash, option uning bandi, textarea ko‘p qatorli matn uchun xizmat qiladi. Bir xil namega ega radio maydonlaridan bittasi tanlanadi; checkbox mustaqil belgilanadi. button type="submit" formani yuborish amalini boshlaydi. Bu darsda faqat brauzerning HTML xatti-harakatini kuzating; tanlovni JavaScript orqali o‘qimang.')
 change(17,teaching='video va audio media elementlaridir. controls brauzer boshqaruv tugmalarini chiqaradi; source src fayl manzili, type media turini bildiradi. preload="metadata" dastlab xizmat ma’lumotlarini yuklashni so‘raydi. Namuna dars.mp4 faylini o‘z kompyuteringizdagi loyiha papkasida talab qiladi. Oddiy matnli bayon video mazmunini tushunishga yordam beradi; JavaScript pleer yozish shart emas.')
 change(18,teaching='head ichida title, meta charset, meta name="viewport" va meta name="description" yoziladi. charset kodlashni, title brauzer yorlig‘i nomini, description mazmun tavsifini bildiradi. Viewport metasi mobil oynaning mantiqiy kengligini belgilaydi; responsive CSS maketi 4-bo‘limda o‘rganiladi. Hozir CSS media query yoki JavaScript qo‘shilmadi.')
 # Other detected instances of later operations appearing too early.
 change(42,task='HTML va CSS bilan navigatsiya havolalarini flex-wrap yordamida tor ekranda yangi qatorga o‘tkazing. Havolalarni bosish uchun yetarli oraliq qoldiring. JavaScript bilan ochilib-yopiladigan menyu talab qilinmaydi.',pitfall='Ekranga sig‘magan havolalarni shunchaki yashirmang. Ochilib-yopiladigan JavaScript menyusi 76-mavzuda o‘rganiladi; bu yerda havolalar doim ko‘rinadi.',teaching='Mobil navigatsiyada avval mavjud HTML havolalariga e’tibor bering. CSS display:flex, gap, flex-wrap va padding bilan o‘qiladigan, bosish qulay ko‘rinish yaratiladi. button va aria-expanded keyingi interaktiv darslar uchun tanishtiriladi, lekin ularni JavaScript bilan boshqarish bu vazifaning sharti emas.')
 change(48,code='<script>\nconsole.log("JavaScript HTMLga ulandi");\n</script>\n<!-- Alohida app.js fayli uchun: <script src="app.js" defer></script> -->',task='HTMLdagi script ichiga console.log bilan xabar yozing va konsolda tekshiring. Kompyuterdagi loyihada shu satrni app.jsga ko‘chiring va src orqali ulang. DOM elementini topish yoki o‘zgartirish talab qilinmaydi.',teaching='script ichidagi matn JavaScript sifatida bajariladi. src tashqi .js fayliga yo‘l beradi; defer tashqi skriptni hujjat o‘qilib bo‘lgach bajaradi. Ichki script va tashqi src usulini alohida sinang. console.log 47-mavzuda ko‘rilgan; document.getElementById va textContent DOM bo‘limida keladi.')
 change(49,code='const kurs = "Frontend";\nlet ism = "Ali";\nconsole.log(kurs);\nconsole.log(ism);\nism = "Vali";\nconsole.log(ism);',expected='Frontend\nAli\nVali',task='const bilan kurs nomini, let bilan o‘quvchi ismini saqlang. Ismni qayta o‘zlashtiring va ikkala holatni console.log bilan chiqaring. Narx hisoblash yoki matematik operator talab qilinmaydi.',teaching='const va let nomlangan qiymat saqlaydi. = o‘zlashtirishdir. constga qayta qiymat berilmaydi; letga beriladi. var eski kodda uchraydi, bu mashqda let va const ishlatiladi. Sonlarni ko‘paytirish va += 51-mavzuda o‘rganiladi.')
 change(52,task='prompt orqali ikkita qiymat oling, Number bilan songa aylantiring va console.log orqali yig‘indini chiqaring. Bo‘sh satr va noto‘g‘ri matnni alohida berib, Number hamda Number.isFinite natijasini kuzating. if bilan rad etish keyingi darsda bajariladi.',teaching='prompt javobni satr sifatida qaytaradi; bekor qilinsa null bo‘lishi mumkin. Number satrni songa aylantiradi, console.log natijani ko‘rsatadi, Number.isFinite son chekliligini tekshiradi. Hozir natijalarni kuzating; if/else sharti 53-mavzuda tushuntirilgach qaror chiqariladi.')
 change(55,code='const a = -8, b = -3;\nlet katta;\nif (a > b) { katta = a; }\nelse { katta = b; }\nconsole.log(katta);',teaching='53-mavzudagi if/else va 51-mavzudagi taqqoslashni qo‘llang. Dastlab ikki sonni taqqoslang, so‘ng uchinchi sonni hozirgi maksimum bilan solishtiring. Yangi ternar sintaksis kiritilmaydi.')
 change(61,code='const ballar = [40, 60, 80];\n// callbackning tayyor qolipi: function(x) { return ...; }\nconsole.log(ballar.map(function(x) { return x + 5; }));\nconsole.log(ballar.filter(function(x) { return x >= 60; }));\nconsole.log(ballar.find(function(x) { return x > 70; }));',task='Berilgan callback qoliplarini saqlang. mapda qo‘shiladigan 5 sonini 10ga, filterdagi 60ni 70ga o‘zgartiring. Natijalarni oldindan yozib, konsol bilan solishtiring. Mustaqil funksiya yoki arrow function yozish shart emas.',teaching='Bu metodlar har bir element uchun callbackni chaqiradi. Tayyor function(x) { return ...; } qolipida x joriy element, return metodga natija uzatadi. Avval shu qolipning ma’nosini tushuning, keyin faqat uning ichidagi arifmetik ifoda yoki shartni o‘zgartiring. Funksiya yaratish keyingi, arrow sintaksisi 64-mavzuda batafsil o‘rganiladi.')
 change(62,code='function salom(ism) {\n console.log("Salom, " + ism);\n}\nsalom("Abdukarim");',task='Ism parametrli salom funksiyasini yozing; uning ichida console.log bilan salomlashuv chiqaring. Funksiyani uch xil ism argumenti bilan chaqiring. return bilan qiymat qaytarish keyingi darsga qoldiriladi.',teaching='function funksiyani e’lon qiladi; qavs ichidagi ism parametrdir. salom("Ali") chaqiruvida "Ali" argument bo‘ladi. Funksiya tanasidagi console.log har chaqiruvda ishlaydi. Hozir natijani ko‘rsatish o‘rganiladi; return orqali hisoblash natijasini qaytarish 63-mavzuning vazifasidir.')
 change(68,code='function ortacha(sonlar) {\n if (!sonlar.length) return null;\n let summa = 0;\n for (let i = 0; i < sonlar.length; i++) summa += sonlar[i];\n return summa / sonlar.length;\n}\nconsole.log(ortacha([40,60,80]));',teaching='56-mavzudagi for, 59-mavzudagi massiv indeksi va 63-mavzudagi returnni birlashtiring. Avval bo‘sh massivni ajrating, keyin siklda yig‘indini hisoblab elementlar soniga bo‘ling. Hali tushuntirilmagan reduce metodini ishlatish shart emas.')
 change(69,code='<h1>Texnikum</h1>\n<p>Frontend kursi</p>\n<script>console.log(document.body.children.length);</script>',task='Namunadagi HTML uchun body → h1 va p → matn tugunlari bog‘lanishini qog‘ozda chizing. Berilgan tayyor konsol satrini kuzating. Elementni qidirish va matnini o‘zgartirish keyingi mavzularda bajariladi.',teaching='DOM — HTMLning brauzer xotirasidagi tugunli ko‘rinishi. document hujjatni, document.body uning body qismini bildiradi; children element farzandlar to‘plami, length ularning sonidir. Skript ham element ekanini hisobga oling. Ushbu tayyor satr faqat kuzatiladi; selektorlar 70-mavzuda, matnni o‘zgartirish 71-mavzuda keladi.')
 change(70,code='<p class="kurs">HTML</p><p class="kurs">CSS</p>\n<p id="xabar">Kurslar ro‘yxati</p>\n<script>\nconsole.log(document.getElementById("xabar"));\nconsole.log(document.querySelector(".kurs"));\nconsole.log(document.querySelectorAll(".kurs").length);\n</script>',task='ID, class va teg orqali elementni topib konsolga chiqaring. Mavjud bo‘lmagan IDni ham sinang va nullni kuzating. Topilgan elementning matni yoki uslubini hozircha o‘zgartirmang.',teaching='getElementById IDni #siz, querySelector CSS selektorini, querySelectorAll barcha mos elementlarni qabul qiladi. Bitta element topilmasa null keladi. Hozir natijani konsolda ko‘ring; textContent orqali o‘zgartirish keyingi mavzu.')
 change(72,task='createElement bilan yangi li yarating, textContent bering va mavjud ulga append qiling. Alohida satrda remove chaqirib farqni kuzating. Inputdan qiymat olish yoki tugma hodisasi keyingi darsga qoldiriladi.',teaching='createElement yangi elementni xotirada yaratadi; textContent matn beradi; append uni sahifaga qo‘shadi; remove sahifadan olib tashlaydi. Avval qo‘shishni sinang, so‘ng remove satrini qo‘shib yana bajaring. click/input hodisalari 73-mavzuda o‘rganiladi.')
 change(79,code='Git — fayllar o‘zgarish tarixini boshqarish vositasi.\nRepository — loyiha va uning tarixi.\nCommit — tarixdagi mazmunli saqlangan holat.\nGitHub — repositoryni onlayn joylash va hamkorlik xizmati.',task='Git va GitHub vazifalarini ajrating. Faylning birinchi va tuzatilgan nusxasi misolida commit tarixining foydasini yozing. Git buyruqlarini bajarish 80-mavzuda o‘rganiladi.',mode='files',expected='O‘quvchi Git, repository, commit va GitHub vazifalarini misol bilan ajratadi; terminal buyrug‘i talab qilinmaydi.',teaching='Bir faylning eski va yangi nusxalarini solishtirishni tasavvur qiling. Git o‘zgarishlar tarixini, GitHub esa onlayn joylash va hamkorlikni ta’minlaydi. git status yoki git log hali mustaqil bajarilmaydi; avval tushunchalar, keyingi darsda o‘rnatish va buyruqlar o‘rganiladi.')
 change(85,code='<pre id="natija">So‘rov yuborilmoqda...</pre>\n<script>\nfetch("https://jsonplaceholder.typicode.com/todos/1")\n .then(function(javob) { return javob.json(); })\n .then(function(data) { document.getElementById("natija").textContent = JSON.stringify(data); })\n .catch(function(xato) { document.getElementById("natija").textContent = String(xato); });\n</script>',task='Avval fetch, json va tayyor then/catch zanjiri izohini o‘qing. Namunada faqat todos/1 manzilini todos/2ga o‘zgartiring va qaytgan JSONni solishtiring. async/await yozish yoki mustaqil Promise zanjiri qurish talab qilinmaydi.',teaching='fetch manzilga so‘rov yuborib kelajak natijani bildiruvchi Promise qaytaradi. Tayyor .then birinchi javob kelganda, keyingisi json o‘qilganda ishlaydi; .catch xato bo‘lsa ishlaydi. javob.json() javob tanasini JSON sifatida o‘qiydi. Ushbu qolipni izohi bilan kuzatib, hozir faqat manzilni o‘zgartiring. Promise zanjirini mustaqil yaratish 86-mavzuda, async/await 87-mavzuda o‘rganiladi.')
 change(20,code='<p style="color:navy">Inline CSS namunasi</p>\n<style>p { color: navy; }</style>\n<!-- Tashqi usulda head ichiga: <link rel="stylesheet" href="style.css"> -->',teaching='Inline CSS elementning style atributiga, internal CSS style tegiga, external CSS esa alohida .css fayliga yoziladi. Tashqi fayl link rel="stylesheet" va href bilan ulanadi. Hozir 19-mavzuda tanishilgan color qoidasini uch xil joyda yozishni solishtiring; yangi dizayn xususiyatlari talab qilinmaydi.')
 change(21,code='<style>\np { color: navy; }\n</style>\n<p>CSS sintaksisi</p>',task='p { color: navy; } qoidasidagi selektor, xususiyat va qiymatni ajrating. Faqat rang qiymatini almashtiring; jingalak qavs, ikki nuqta va nuqtali vergulning vazifasini ayting.',teaching='p — selektor, color — xususiyat, navy — qiymat. Deklaratsiya xususiyat: qiymat; ko‘rinishida, qoida esa selektor { deklaratsiya } ko‘rinishida yoziladi. Bu darsning maqsadi yangi dizayn xususiyatlarini ko‘paytirish emas, sintaksisni tushunishdir.')
 change(22,code='<style>p { color: navy; } .kurs { color: green; } #kirish { color: brown; }</style>\n<p id="kirish" class="kurs">Kirish</p><p class="kurs">Davom</p>',task='Ikki paragrafga umumiy class, bittasiga yagona id bering. Element, class va ID selektorlarini color bilan solishtiring; padding yoki maket qo‘shmang.',teaching='p element nomini, .kurs class qiymatini, #kirish ID qiymatini tanlaydi. HTML class va id atributlari selektor bilan bog‘lanadi. Bitta elementga bir nechta qoida mos kelsa, shu misolda ID qoidasining maxsusligi yuqori. Hozir faqat oldin o‘tilgan color bilan natijani kuzating.')
 change(23,code='<style>.eslatma { color: #173f34; background-color: rgb(233,243,236); }</style>\n<p class="eslatma">O‘qilishi oson ranglar</p>',teaching='color matn rangini, background-color fon rangini belgilaydi. Rang nomi, # bilan HEX va rgb(qizil,yashil,ko‘k) usullarini solishtiring. Matn fon ustida yaxshi o‘qilishi kerak. Bu darsda padding va joylashuv talab qilinmaydi.')
 change(24,code='<style>body { font-family: Arial, sans-serif; } h1 { font-size: 30px; font-weight: 700; } p { font-size: 18px; line-height: 1.6; text-align: left; }</style>\n<h1>Kurs sarlavhasi</h1><p>O‘qiladigan matn.</p>',teaching='font-family shriftlar ketma-ketligini, font-size bu misolda pxdagi o‘lchamni, font-weight qalinlikni, line-height qator balandligini va text-align tekislanishni belgilaydi. 700 qalin shrift vazni, 1.6 esa shrift o‘lchamiga nisbiy qator koeffitsiyentidir. rem va viewport birliklari keyingi responsive bo‘limda o‘rganiladi.')
 change(26,code='<style>.karta { border: 2px solid green; border-radius: 12px; } button { outline: 2px solid navy; }</style>\n<div class="karta"><h2>Kurs kartasi</h2><button>Boshlash</button></div>',task='Kartaga border va border-radius bering. Tugmaga doim ko‘rinadigan outline qo‘shib, borderdan farqini kuzating. :focus va :hover qoidalarini yozish bu darsda talab qilinmaydi.',teaching='border kenglik, uslub va rang bilan yoziladi; border-radius burchakni yumaloqlaydi. outline element tashqarisidagi belgi bo‘lib, maket uchun border kabi joy egallamaydi. Hozir outline doim ko‘rinadigan oddiy qoida bilan beriladi; holat selektorlari 34-mavzuda keladi.')
 change(32,code='<style>.kartalar { display: flex; gap: 16px; justify-content: center; align-items: center; flex-wrap: wrap; } .karta { width: 180px; padding: 20px; background: #edf4ef; }</style>\n<div class="kartalar"><div class="karta">1</div><div class="karta">2</div><div class="karta">3</div></div>',teaching='display:flex bolalarni asosiy o‘q bo‘ylab joylaydi. justify-content asosiy o‘q, align-items ko‘ndalang o‘q tekislanishini, gap oraliqni, flex-wrap esa sig‘magan bolalarning yangi qatorga o‘tishini boshqaradi. Hozir eni 180px bo‘lgan kartalar bilan ishlang; flex-grow, shrink va basis tafsilotlari 40-mavzuda keladi.')
 change(33,task='grid-template-columns: repeat(3, 1fr) bilan uch teng ustun va gap yarating. grid-column: span 2 bilan bitta kartani ikki ustunga yoyib natijani solishtiring.',teaching='display:grid konteynerni panjaraga aylantiradi. grid-template-columns ustunlarni, repeat(3,1fr) uch teng ulushni, gap oraliqni bildiradi. grid-column:span 2 elementni ikki ustunga yoyadi. minmax(min,max) trekning eng kichik va katta chegarasini ifodalaydi; auto-fit bilan responsive shakl 41-mavzuda keladi.')
 L[10]['terms'][-1]=['Fayl yo‘li','Rasmning joylashuvini ko‘rsatadi: to‘liq HTTPS manzili yoki loyiha papkasiga nisbiy yo‘l bo‘lishi mumkin.']
